import { Buffer } from 'node:buffer';
import events from './events.json' with {type: 'json'};

const TOOL_NAME = 'events_list';
const ALLOWED_KEYS = new Set(['cursor', 'page_size']);
const DEFAULT_PAGE_SIZE = 2;
const MIN_PAGE_SIZE = 1;
const MAX_PAGE_SIZE = 3;

function encodeCursor(index) {
  return Buffer.from(JSON.stringify({i: index}), 'utf8').toString('base64');
}

function decodeCursor(cursor) {
  let raw;
  try {
    raw = Buffer.from(cursor, 'base64').toString('utf8');
  } catch {
    throw new Error('Invalid cursor');
  }
  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch {
    throw new Error('Invalid cursor');
  }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
    throw new Error('Invalid cursor');
  }
  if (typeof parsed.i !== 'number' || !Number.isInteger(parsed.i)) {
    throw new Error('Invalid cursor');
  }
  if (parsed.i < 0 || parsed.i >= events.length) {
    throw new Error('Invalid cursor');
  }
  return parsed.i;
}

export async function listTools() {
  return [
    {
      name: TOOL_NAME,
      description: 'List events in source order with opaque cursor pagination.',
      inputSchema: {
        type: 'object',
        properties: {
          cursor: {
            type: 'string',
            description: 'Opaque cursor returned by a previous call. Omit for the first page.'
          },
          page_size: {
            type: 'integer',
            minimum: MIN_PAGE_SIZE,
            maximum: MAX_PAGE_SIZE,
            description: 'Number of events to return per page (1-3). Defaults to 2.'
          }
        },
        additionalProperties: false,
        required: []
      }
    }
  ];
}

export async function callTool(name, args) {
  if (name !== TOOL_NAME) {
    throw new Error(`Unknown tool: ${name}`);
  }

  if (args === null || args === undefined) {
    args = {};
  }
  if (typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Invalid arguments: expected an object');
  }
  for (const key of Object.keys(args)) {
    if (!ALLOWED_KEYS.has(key)) {
      throw new Error(`Unknown field: ${key}`);
    }
  }

  let pageSize = DEFAULT_PAGE_SIZE;
  if (Object.prototype.hasOwnProperty.call(args, 'page_size')) {
    const v = args.page_size;
    if (typeof v !== 'number' || !Number.isInteger(v) || v < MIN_PAGE_SIZE || v > MAX_PAGE_SIZE) {
      throw new Error(`page_size must be an integer between ${MIN_PAGE_SIZE} and ${MAX_PAGE_SIZE}`);
    }
    pageSize = v;
  }

  let startIndex = 0;
  if (Object.prototype.hasOwnProperty.call(args, 'cursor')) {
    const v = args.cursor;
    if (typeof v !== 'string') {
      throw new Error('cursor must be a string');
    }
    startIndex = decodeCursor(v);
  }

  const endIndex = Math.min(startIndex + pageSize, events.length);
  const page = events.slice(startIndex, endIndex);
  const hasMore = endIndex < events.length;

  const payload = {events: page};
  if (hasMore) {
    payload.next_cursor = encodeCursor(endIndex);
  }

  return {
    content: [{type: 'text', text: JSON.stringify(payload)}]
  };
