import { spawn } from 'node:child_process';
import readline from 'node:readline';

const p = spawn('node', ['./protocol.mjs']);
const rl = readline.createInterface({input: p.stdout});
const errs = [];
p.stderr.on('data', d => errs.push(d.toString()));

let nextId = 1;
const pending = new Map();
rl.on('line', line => {
  const msg = JSON.parse(line);
  const cb = pending.get(msg.id);
  pending.delete(msg.id);
  if (cb) cb(msg);
});

function call(params) {
  const id = nextId++;
  return new Promise(resolve => {
    pending.set(id, resolve);
    p.stdin.write(JSON.stringify({jsonrpc:'2.0', id, method:'tools/call', params}) + '\n');
  });
}

const out = [];
const r1 = await call({name:'events_list', arguments:{page_size:1}});
const t1 = JSON.parse(r1.result.content[0].text);
out.push('P1: ' + t1.events.map(e=>e.id).join(',') + '  cursor=' + ('next_cursor' in t1));
let cur = t1.next_cursor;

if (cur) {
  const r2 = await call({name:'events_list', arguments:{page_size:1, cursor:cur}});
  const t2 = JSON.parse(r2.result.content[0].text);
  out.push('P2: ' + t2.events.map(e=>e.id).join(',') + '  cursor=' + ('next_cursor' in t2));
  cur = t2.next_cursor;
}
if (cur) {
  const r3 = await call({name:'events_list', arguments:{page_size:1, cursor:cur}});
  const t3 = JSON.parse(r3.result.content[0].text);
  out.push('P3: ' + t3.events.map(e=>e.id).join(',') + '  cursor=' + ('next_cursor' in t3));
  cur = t3.next_cursor;
}
if (cur) {
  const r4 = await call({name:'events_list', arguments:{page_size:1, cursor:cur}});
  const t4 = JSON.parse(r4.result.content[0].text);
  out.push('P4: ' + t4.events.map(e=>e.id).join(',') + '  cursor=' + ('next_cursor' in t4));
}

console.log(out.join('\n'));
if (errs.length) console.error('stderr:', errs.join(''));
p.kill();

